fn with_layout<T>(
    docx: &[u8],
    emit: impl FnOnce(&Fonts, &[pdf::Page], &LayoutFacts) -> T,
) -> Result<T, ConvertError> {
    crate::document_comparer::admit_package(docx)
        .map_err(|err| ConvertError::OpenPackage(err.to_string()))?;
    let normalized = crate::strict_translation::strict_to_transitional_docx(docx)
        .map_err(|err| ConvertError::OpenPackage(err.to_string()))?;
    let pkg =
        PartFs::open(&normalized).map_err(|err| ConvertError::OpenPackage(format!("{err:?}")))?;
    let main = pkg
        .main_document_part()
        .or_else(|| {
            pkg.part_bytes("word/document.xml")
                .map(|_| "word/document.xml".to_string())
        })
        .ok_or(ConvertError::MissingDocument)?;
    let xml = pkg
        .part_string(&main)
        .ok_or(ConvertError::MissingDocument)?;
    // Word merges `w:altChunk` content (HTML / MHT) into the body on open.
    let xml = if xml.contains("<w:altChunk") {
        altchunk::expand(&xml, |rid| {
            rel_target_path(&pkg, &main, rid).and_then(|p| pkg.part_bytes(&p).map(<[u8]>::to_vec))
        })
    } else {
        xml
    };
    let mut dom = Dom::new();
    let doc = dom.parse_xdocument(&xml);
    let root = dom.root(doc).ok_or(ConvertError::MissingDocument)?;
    let body = dom
        .descendants(root, Some(&W::body()))
        .into_iter()
        .next()
        .ok_or(ConvertError::MissingDocument)?;

    let table = font_table::load_font_table(&pkg);
    let mut embedded = font_table::load_embedded_fonts(&pkg, &table);

let remaining = limits.max_uncompressed_bytes.saturating_sub(total);
let cap = limits.max_part_bytes.min(remaining);
let lower = name.to_ascii_lowercase();
let is_xml = lower.ends_with(".xml") || lower.ends_with(".rels");
let mut limited = (&mut entry).take(cap.saturating_add(1));
let read = if is_xml {
    let mut buf = Vec::new();
    limited
        .read_to_end(&mut buf)
        .map_err(|e| AdmissionError::new(K::InvalidPackage, format!("{name}: {e}")))?;
    let n = buf.len() as u64;
    if n <= cap {
        check_xml_depth(&name, &buf, limits)?;
        if lower == "[content_types].xml" || lower == "_rels/.rels" {
            kept.insert(lower, buf);
        }
    }
    n
} else {
    std::io::copy(&mut limited, &mut std::io::sink())
        .map_err(|e| AdmissionError::new(K::InvalidPackage, format!("{name}: {e}")))?
};
tally_inflated(&mut total, read, &name, cap, &limits)?;

let main_part = main_part(&archive, &kept)?;
// The scan above is by extension; the main part is parsed whatever it is
// called, so one named otherwise is read once more for its depth.
let lower = main_part.to_ascii_lowercase();
if !(lower.ends_with(".xml") || lower.ends_with(".rels")) {
    let mut entry = archive
        .by_name(&main_part)
        .map_err(|e| AdmissionError::new(K::InvalidPackage, format!("{main_part}: {e}")))?;
    let mut buf = Vec::new();
    (&mut entry)
        .take(limits.max_part_bytes.saturating_add(1))
        .read_to_end(&mut buf)
        .map_err(|e| AdmissionError::new(K::InvalidPackage, format!("{main_part}: {e}")))?;
    check_xml_depth(&main_part, &buf, limits)?;
}

