            bucket.push(pkg.resolve_rel_target(&main, &r.target));
        }
    }
    let mut out = vec![(main, false)];
    for p in headers
        .into_iter()
        .chain(footers)
        .chain(endnotes)
        .chain(footnotes)
        .chain(comments)
    {
        out.push((p, false));
    }
    for p in styles {
        out.push((p, true));
    }

