font::add_installed_faces(&mut embedded, &table, &family_names, &run_faces, has_cjk);
if has_cjk {
    font::add_cjk_fallbacks(&mut embedded);
}

// East Asian families named only in styles or the theme ("宋体" as the
// theme's Hans font) are not in the font table but Word draws them.
for name in extra {
    let lower = name.to_ascii_lowercase();
    let painted = run_faces.iter().any(|n| n == name);
    let wanted = if cjk_file_stems(name).is_empty() {
        painted && !catalogue_paints_family(name)
    } else {
        has_cjk || painted
    };
    if !wanted || table.get(name).is_some() || embedded.keys().any(|(f, _, _)| *f == lower) {
        continue;
    }
    // A family runs name but the table omits (015beda9 has no table
    // part; Word still draws its Segoe UI) loads like a table family.
    let mut faces = cached_faces(name, || installed_family_faces(name));
    if faces.is_empty()
        && let Some(sub) = super::word_subst::word_name_substitute(name)

pub(crate) fn installed_family_faces(family: &str) -> Vec<((bool, bool), Vec<u8>)> {
    let stems = cjk_file_stems(family);
    if !stems.is_empty() {
        return cjk_family_faces(family, stems);
    }
    let user = user_font_dir();
    let cloud_root = std::env::var_os("HOME")
        .and_then(|home| cloud_font_dir(Path::new(&home), "x"))
        .and_then(|d| d.parent().map(Path::to_path_buf));
    let key = format!(
        "family\u{1f}{family}\u{1f}{}\u{1f}{}",
        user.as_deref().unwrap_or(Path::new("")).display(),
        cloud_root.as_deref().unwrap_or(Path::new("")).display()
    );
    indexed_faces(&FONT_INDEX, &key, || {
        let (faces, mut dirs) = scan_family_faces(family, user.as_deref());
        dirs.extend(cloud_root.clone());
        (faces, dirs)
    })

